154: 
155:         // 逐层预占额度 → 创建借据（Fineract 贷款账户）→ 提交付款
156:         limitService.preOccupy(quote.getCreditId(), order.getBizOrderNo(), version.getProductId(),
157:                 version.isRequiresGuarantee(), quote.getAmount());
